import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { inflateSync } from 'node:zlib';
import initWasm, { HwpDocument } from '@rhwp/core';
import { strFromU8, strToU8, unzipSync, zipSync } from 'fflate';
import { bodyLocation, nextFigureNumber, outlineCounters as bodyOutlineCounters, readHeaderXml, readSectionXml,
  styleMismatches, topLevelParagraphRanges, withEngineBullets } from './hwpx-read.js';
import { detectForm, getForm } from './forms.js';
import { looksLikeSvg, svgInfo } from './svg.js';

const SECTION = 0;
const SECTION_ENTRY = 'Contents/section0.xml';
// cell path of a top-level paragraph (no enclosing table cell) for the rhwp copy/paste calls
const TOP_LEVEL_PATH = '[]';
const TABLE_HEADER_BORDER_FILL_ID = 17;
const FIGURE_TABLE_BORDER_FILL_ID = 4;
const FIGURE_CELL_BORDER_FILL_ID = 15;
// rhwp table pageBreak value for "do not split the table across pages" (HWPX pageBreak="NONE").
const FIGURE_TABLE_NO_SPLIT = 0;
// Caption row height estimate (HWPUNIT): 11 pt caption lines at 160% line spacing plus cell
// padding; the line count assumes one full-width character per 1,100 HWPUNIT of table width.
const CAPTION_LINE_HU = 1760;
const CAPTION_PADDING_HU = 600;
const CAPTION_CHAR_HU = 1100;
function captionRowHu(caption, tableWidth) {
  const perLine = Math.max(1, Math.floor(tableWidth / CAPTION_CHAR_HU));
  return Math.ceil(Math.max(1, [...caption].length) / perLine) * CAPTION_LINE_HU + CAPTION_PADDING_HU;
}
const TABLE_WIDTH_SAFETY_INSET_HU = 200;

// Levels 1-3 render their marker via paraPr <hh:heading type="BULLET"> (sample contract);
// only level 4 (heading NONE) carries a literal "  ·" in text, as the sample form does.
export const BULLET_STYLES = {
  bullet1: { prefix: '', style: 0, paraPr: 59, charPr: 46 },
  bullet2: { prefix: '', style: 0, paraPr: 60, charPr: 46 },
  bullet3: { prefix: '', style: 0, paraPr: 61, charPr: 46 },
  bullet4: { prefix: '  ·', style: 0, paraPr: 62, charPr: 46 },
};

// Strong bullet glyphs strip even when glued to the text; ㅇ (U+3147) only when it reads
// as a marker (before whitespace or a full syllable - leaves ㅇㅇ placeholders intact);
// dashes only before whitespace (protects negative numbers).
const LEADING_MARKER_RE = /^(?:[◎⚪○◯●•·ㆍ\u00ad]|[-‐‑–—](?=\s)|ㅇ(?=\s|[가-힣]))\s*/;

export function stripLeadingBulletMarkers(text) {
  let stripped = text.trimStart();
  while (LEADING_MARKER_RE.test(stripped)) {
    stripped = stripped.replace(LEADING_MARKER_RE, '');
  }
  return stripped;
}

// The <hh:bullets> container rhwp drops on export is restored from withEngineBullets (hwpx-read.js).

// A figure caption closes its figure: space after it separates the figure from the text.
const CAPTION_STYLE = { style: 0, paraPr: 57, charPr: 50 };
const FIGURE_CAPTION_STYLE = { ...CAPTION_STYLE, format: { spacingAfter: 800 } };
// A table title sits above its table and must not end a page on its own.
const TABLE_CAPTION_STYLE = { ...CAPTION_STYLE, format: { keepWithNext: true, spacingBefore: 400 } };
// A figure's carrier paragraph keeps with its caption. The paragraph that follows a content
// table gets space before it so it does not touch the table border (rhwp ignores
// spacing-after on a table carrier paragraph).
const FIGURE_CARRIER_FORMAT = { keepWithNext: true, spacingBefore: 200 };
const AFTER_TABLE_SPACING = 800;

// Outline levels of the institute's research-report form ("연구수행 내용 및 성과"):
// numbered headings 가. / 1) / (1), ◯ statements and - details. The engine writes the
// label; margins (HWPUNIT, rhwp paraPr default values) are applied through
// applyParaFormatInCell, which finds or creates the matching paraPr on a plain base.
// A negative indent is a hanging indent: the first line starts at marginLeft and the
// following lines move right by |indent| (◯/- text aligns under the text, not the mark).
// Offsets follow the reference form's rendered proportions (1) ≈ 1.2, (1) ≈ 2.2,
// ◯ ≈ 3.0 and - ≈ 3.9 character widths; wrapped text ≈ 4.5).
// Headings keep with the next paragraph so a title never ends a page alone.
const OUTLINE_BASE_PARA_PR = 58;
const HANGUL_ORDINALS = '가나다라마바사아자차카타파하';
export const OUTLINE_STYLES = {
  heading1: { style: 0, paraPr: OUTLINE_BASE_PARA_PR, charPr: 6, counter: 0,
    label: (n) => `${HANGUL_ORDINALS[n]}.`,
    format: { marginLeft: 0, indent: 0, spacingBefore: 1200, keepWithNext: true } },
  heading2: { style: 0, paraPr: OUTLINE_BASE_PARA_PR, charPr: 46, counter: 1,
    label: (n) => `${n + 1})`,
    format: { marginLeft: 2600, indent: 0, spacingBefore: 600, keepWithNext: true } },
  heading3: { style: 0, paraPr: OUTLINE_BASE_PARA_PR, charPr: 46, counter: 2,
    label: (n) => `(${n + 1})`,
    format: { marginLeft: 4800, indent: 0, spacingBefore: 300, keepWithNext: true } },
  statement: { style: 0, paraPr: OUTLINE_BASE_PARA_PR, charPr: 46, prefix: '◯ ',
    format: { marginLeft: 6600, indent: -3200, spacingBefore: 0 } },
  detail: { style: 0, paraPr: OUTLINE_BASE_PARA_PR, charPr: 46, prefix: '- ',
    format: { marginLeft: 8600, indent: -1200, spacingBefore: 0 } },
};
export const OUTLINE_LABEL_RE = /^(?:[가-하]\.|\d+\)|\(\d+\))\s/;

export function outlineLabel(counters, type) {
  const spec = OUTLINE_STYLES[type];
  if (spec.counter === undefined) {
    return spec.prefix;
  }
  const n = counters[spec.counter];
  if (spec.counter === 0 && n >= HANGUL_ORDINALS.length) {
    throw new Error(`heading1 supports at most ${HANGUL_ORDINALS.length} sections`);
  }
  counters[spec.counter] += 1;
  counters.fill(0, spec.counter + 1);
  return `${spec.label(n)} `;
}

function captionText(block, number) {
  return block.captionStyle === 'angle' ? `<${block.caption ?? ''}>` : `그림 ${number}. ${block.caption ?? ''}`;
}
const TABLE_TEXT_STYLE = { style: 22, paraPr: 5, charPr: 53 };
// Body cells of a column that holds sentences read left-aligned; short labels and numbers stay
// centred. Character width/spacing follow the body text (ratio 95) so cells do not look spaced out.
const TABLE_TEXT_COLUMN_MIN_CHARS = 15;
const TABLE_BODY_LEFT_FORMAT = { alignment: 'left' };
const TABLE_CHAR_FORMAT = { ratio: 95, spacing: -5 };
// Vertical cell padding (HWPUNIT) so text does not touch the cell borders.
const TABLE_CELL_PADDING = { paddingTop: 280, paddingBottom: 280, applyInnerMargin: true };

let wasmReady;
// the form (engine/forms/<id>) of each open document; see formOf
const documentForms = new WeakMap();

export class ImageDecodeError extends Error {
  constructor(imagePath, cause) {
    const detail = cause instanceof Error && cause.message ? `: ${cause.message}` : '';
    super(`failed to decode image ${imagePath}${detail}`);
    this.name = 'ImageDecodeError';
    this.imagePath = imagePath;
    this.cause = cause;
  }
}

globalThis.measureTextWidth = globalThis.measureTextWidth ?? ((font, text) => {
  const size = parseFloat(font) || 10;
  let width = 0;
  for (const ch of text) {
    width += ch.codePointAt(0) > 0x2e80 ? size : size * 0.55;
  }
  return width;
});

export async function appendBlocks(inputPath, outputPath, draft, projectRoot) {
  await ensureWasm();

  const initialXml = readSectionXml(inputPath);
  const mismatches = styleMismatches(readHeaderXml(inputPath));
  if (mismatches.length > 0) {
    throw new Error(`the document's styles differ from the engine's forms (${mismatches.slice(0, 5).join(', ')}); `
      + 'it cannot be continued. Start a new report from a form, or add this document as a form (references/draft-format.md)');
  }
  let figureNumber = nextFigureNumber(initialXml);
  let firstFigure = null;
  let lastFigure = null;

  const doc = new HwpDocument(new Uint8Array(readFileSync(inputPath)));
  const form = formOf(initialXml, draft.template);
  documentForms.set(doc, form);
  prepareBodyEnd(doc);
  const blocks = draft.blocks ?? [];
  // numbering goes on from the headings already in the body (a continuation starts after them)
  const outlineCounters = bodyOutlineCounters(initialXml, form);
  // an append that continues right after a table or figure gets the same spacing
  let afterTable = previousParagraphHoldsTable(doc);
  const spaced = (style) => (afterTable
    ? { ...style, format: { ...style.format,
      spacingBefore: Math.max(style.format?.spacingBefore ?? 0, AFTER_TABLE_SPACING) } }
    : style);
  for (const block of blocks) {
    if (OUTLINE_STYLES[block.type]) {
      const stripped = stripLeadingBulletMarkers(block.text ?? '');
      if (!stripped) {
        throw new Error(`${block.type} text is empty after leading marker strip: ${JSON.stringify(block.text ?? '')}`);
      }
      insertStyledParagraph(doc, `${outlineLabel(outlineCounters, block.type)}${stripped}`,
        spaced(OUTLINE_STYLES[block.type]));
    } else if (BULLET_STYLES[block.type]) {
      const stripped = stripLeadingBulletMarkers(block.text ?? '');
      if (!stripped) {
        throw new Error(`${block.type} text is empty after leading bullet-marker strip: ${JSON.stringify(block.text ?? '')}`);
      }
      insertStyledParagraph(doc, `${BULLET_STYLES[block.type].prefix}${stripped}`, spaced(BULLET_STYLES[block.type]));
    } else if (block.type === 'figure_grid') {
      const current = figureNumber;
      insertFigureGrid(doc, block, projectRoot, afterTable);
      if (block.captionStyle === 'angle') {
        // the <caption> sits in the figure table's last row; space goes before what follows
        afterTable = true;
        continue;
      }
      insertStyledParagraph(doc, captionText(block, current), FIGURE_CAPTION_STYLE);
      firstFigure ??= current;
      lastFigure = current;
      figureNumber += 1;
    } else if (block.type === 'table') {
      if (block.caption) {
        insertStyledParagraph(doc, `<${block.caption}>`, spaced(TABLE_CAPTION_STYLE));
      }
      // a table directly after a table (no title between them) gets the space on its carrier
      insertContentTable(doc, block, afterTable && !block.caption);
      afterTable = true;
      continue;
    } else {
      throw new Error(`unsupported block type: ${block.type}`);
    }
    afterTable = false;
  }

  placeContentTables(doc);
  if (draft.form) {
    fillForm(doc, draft.form);
  }
  const { bytes, layout } = paginate(doc.exportHwpx(), form);
  writeFileSync(outputPath, Buffer.from(bytes));
  return {
    figuresAdded: firstFigure === null ? null : [firstFigure, lastFigure],
    blocks: blocks.length,
    form: form.id,
    layout,
  };
}

// The form of the document being written: the one detected from its content; a draft that names
// a template must match it (a new report starts from that template's skeleton).
function formOf(xml, template) {
  const detected = detectForm(xml);
  if (template && getForm(template).id !== detected.id) {
    throw new Error(`the draft asks for form "${template}" but the target document is form "${detected.id}"`);
  }
  return detected;
}

// A form whose body runs to the end of the document writes before an empty last paragraph; a
// document that ends in text, a table or the section settings gets one first.
function prepareBodyEnd(doc) {
  const form = documentForms.get(doc);
  if (form.body.end !== 'document') {
    return;
  }
  const location = bodyLocation(sectionXml(doc), form);
  if (!location.endEmpty) {
    parseOk(doc.splitParagraph(SECTION, location.endIdx, doc.getParagraphLength(SECTION, location.endIdx)));
  }
}

// The form's own parts (engine/forms/<id>/form.json): the title paragraph (form.title), a goal
// table found by its header text that gets one body row per goal (form.goals), and the body rows
// of the table that ends the body (form.summary). Each is filled only while it is still empty, so
// an append never overwrites what a reviewer typed in Hancom.
function fillForm(doc, values) {
  const form = documentForms.get(doc);
  const need = (key, spec) => {
    if (!spec) {
      throw new Error(`form.${key}: form "${form.id}" has no ${key}`);
    }
    return spec;
  };
  if (values.title) {
    const spec = need('title', form.title);
    const length = doc.getParagraphLength(SECTION, spec.paragraph);
    const own = /<hp:t>([^<]*)<\/hp:t>/g;
    const xml = sectionXml(doc);
    const paragraph = topLevelParagraphRanges(xml)[spec.paragraph];
    const text = [...xml.slice(paragraph.start, paragraph.end).matchAll(own)].map((m) => m[1]).join('');
    if (text.trim()) {
      throw new Error('form.title: the title paragraph already has text');
    }
    parseOk(doc.insertText(SECTION, spec.paragraph, length, values.title));
    const format = { ...(spec.align ? { alignment: spec.align } : {}),
      ...(spec.spacingAfter ? { spacingAfter: spec.spacingAfter } : {}) };
    if (Object.keys(format).length > 0) {
      parseOk(doc.applyParaFormat(SECTION, spec.paragraph, JSON.stringify(format)));
    }
  }
  if (values.goals) {
    const spec = need('goals', form.tables?.goals);
    checkFormRows('goals', values.goals, spec);
    const goal = goalTableLocation(sectionXml(doc), spec.header);
    if (goal.bodyText.trim()) {
      throw new Error('form.goals: the goal table already has content');
    }
    for (let row = 1; row < values.goals.length; row += 1) {
      parseOk(doc.insertTableRow(SECTION, goal.paraIdx, 0, row, true));
    }
    values.goals.forEach((cells, row) => cells.forEach((text, col) => {
      if (text) {
        const cell = (row + 1) * spec.columns + col;
        parseOk(doc.insertTextInCell(SECTION, goal.paraIdx, 0, cell, 0, 0, text));
        if (spec.align?.[col]) {
          parseOk(doc.applyParaFormatInCell(SECTION, goal.paraIdx, 0, cell, 0,
            JSON.stringify({ alignment: spec.align[col] })));
        }
      }
    }));
    fitTableRows(doc, goal.paraIdx, (xml) => xml.lastIndexOf('<hp:tbl', xml.indexOf(spec.header)));
  }
  if (values.summary) {
    const spec = need('summary', form.tables?.summary);
    checkFormRows('summary', values.summary, spec);
    const anchor = resolveAnchor(doc);
    if (!anchor.endTable) {
      throw new Error(`form.summary: form "${form.id}" has no table at the end of the body`);
    }
    const summaryXml = anchor.xml.slice(anchor.endTable.start, anchor.endTable.end);
    const body = summaryXml.split(/<hp:tr\b/).slice(2).join('');
    if ([...body.matchAll(/<hp:t>([^<]*)<\/hp:t>/g)].some((m) => m[1].trim())) {
      throw new Error('form.summary: the closing form table already has content');
    }
    values.summary.forEach((cells, row) => cells.forEach((text, col) => {
      if (text) {
        const cell = (row + 1) * spec.columns + col;
        parseOk(doc.insertTextInCell(SECTION, anchor.endIdx, 0, cell, 0, 0, text));
        dropTrailingEmptyCellParagraphs(doc, anchor.endIdx, cell);
      }
    }));
    fitTableRows(doc, anchor.endIdx, (xml) => bodyLocation(xml, form).endTable.start);
  }
}

function checkFormRows(key, rows, spec) {
  if (rows.length > spec.maxRows || rows.some((row) => row.length !== spec.columns)) {
    throw new Error(`form.${key}: at most ${spec.maxRows} rows of ${spec.columns} cells`);
  }
}

// The form's empty cells hold blank guide lines; left under the filled text they would push it
// up in a vertically centred cell and make the row taller.
function dropTrailingEmptyCellParagraphs(doc, paraIdx, cell) {
  const count = doc.getCellParagraphCount(SECTION, paraIdx, 0, cell);
  const lengths = Array.from({ length: count }, (_, i) => doc.getCellParagraphLength(SECTION, paraIdx, 0, cell, i));
  let last = count - 1;
  while (last > 0 && lengths[last] === 0) {
    last -= 1;
  }
  if (last < count - 1) {
    parseOk(doc.deleteRangeInCell(SECTION, paraIdx, 0, cell, last, lengths[last], count - 1, 0));
  }
}

// rhwp keeps a row at its stored height even when the filled text wraps, so a second line is
// drawn under the next row. Give every body row the height of its tallest cell (last line bottom
// plus the cell's top and bottom margins).
function fitTableRows(doc, paraIdx, locateTable, { header = false } = {}) {
  const xml = sectionXml(doc);
  const tableStart = locateTable(xml);
  const tableXml = xml.slice(tableStart, tagEnd(xml, 'hp:tbl', tableStart));
  const rows = tableXml.split(/<hp:tr\b/).slice(1);
  // a cell with hasMargin="0" uses the table's inner margin, not its own cellMargin
  const tableMargin = tableXml.slice(0, tableXml.indexOf('<hp:tr'))
    .match(/<hp:inMargin\b[^>]*\btop="(\d+)"[^>]*\bbottom="(\d+)"/);
  let cellIdx = 0;
  rows.forEach((row, r) => {
    const cells = row.split(/<hp:tc\b/).slice(1).map((tc) => {
      const bottoms = [...tc.matchAll(/<hp:lineseg\b[^>]*\bvertpos="(\d+)"[^>]*\bvertsize="(\d+)"/g)]
        .map((m) => Number(m[1]) + Number(m[2]));
      const ownMargin = /^[^>]*\bhasMargin="1"/.test(tc);
      const margin = ownMargin ? tc.match(/<hp:cellMargin\b[^>]*\btop="(\d+)"[^>]*\bbottom="(\d+)"/) : tableMargin;
      const height = Number(tc.match(/<hp:cellSz\b[^>]*\bheight="(\d+)"/)?.[1] ?? 0);
      const content = Math.max(0, ...bottoms) + (margin ? Number(margin[1]) + Number(margin[2]) : 0);
      return { height, content };
    });
    const target = Math.max(...cells.map((c) => Math.max(c.height, c.content)));
    cells.forEach((c) => {
      if ((header || r > 0) && target > c.height) {
        parseOk(doc.setCellProperties(SECTION, paraIdx, 0, cellIdx, JSON.stringify({ height: target })));
      }
      cellIdx += 1;
    });
  });
}

function goalTableLocation(xml, headerText) {
  const header = xml.indexOf(headerText);
  if (header < 0) {
    throw new Error(`form.goals: no table with the header "${headerText}"`);
  }
  const tableStart = xml.lastIndexOf('<hp:tbl', header);
  const tableXml = xml.slice(tableStart, tagEnd(xml, 'hp:tbl', tableStart));
  const paraIdx = topLevelParagraphRanges(xml).filter((paragraph) => paragraph.end <= tableStart).length;
  const bodyRows = tableXml.split(/<hp:tr\b/).slice(2).join('');
  const bodyText = [...bodyRows.matchAll(/<hp:t>([^<]*)<\/hp:t>/g)].map((m) => m[1]).join('');
  return { paraIdx, bodyText };
}

// Deterministic post-export repairs of rhwp serializer gaps, plus the page breaks chosen by
// paginate:
// 1. restore the <hh:bullets> container it drops (dangling paraPr BULLET idRefs otherwise);
// 2. re-anchor pasted inline tables and pictures from vertRelTo="PAGE" to "PARA" —
//    pasteInternalInCellByPath emits PAGE. The form skeletons contain no treat-as-char object
//    with vertRelTo="PAGE", so the rewrite only touches engine-generated objects;
// 3. set pageBreak="1" on the top-level paragraphs listed in `breaks` (paragraph indices);
// 4. set the final pageBreak (NONE/CELL) of the body tables listed in `tableBreaks`;
// 5. store mimetype as the first, uncompressed zip entry.
function normalizeExport(hwpxBytes, breaks = new Set(), tableBreaks = new Map()) {
  const entries = unzipSync(hwpxBytes);
  let changed = false;

  const header = strFromU8(entries['Contents/header.xml']);
  const restored = withEngineBullets(header);
  if (restored !== header) {
    entries['Contents/header.xml'] = strToU8(restored);
    changed = true;
  }

  const section = strFromU8(entries[SECTION_ENTRY]);
  let rewritten = section.replace(
    /<hp:pos\b[^>]*\/>/g,
    (tag) => (tag.includes('treatAsChar="1"') && tag.includes('vertRelTo="PAGE"')
      ? tag.replace('vertRelTo="PAGE"', 'vertRelTo="PARA"')
      : tag),
  );
  if (breaks.size > 0) {
    const ranges = topLevelParagraphRanges(rewritten);
    for (const index of [...breaks].sort((a, b) => b - a)) {
      const start = ranges[index].start;
      const end = rewritten.indexOf('>', start) + 1;
      const tag = rewritten.slice(start, end).replace(/\spageBreak="\d"/, ' pageBreak="1"');
      rewritten = rewritten.slice(0, start) + tag + rewritten.slice(end);
    }
  }
  if (tableBreaks.size > 0) {
    const ranges = topLevelParagraphRanges(rewritten);
    for (const [index, value] of [...tableBreaks].sort((a, b) => b[0] - a[0])) {
      const start = rewritten.indexOf('<hp:tbl', ranges[index].start);
      const end = rewritten.indexOf('>', start) + 1;
      const tag = rewritten.slice(start, end);
      if (start < ranges[index].end && tag.includes('repeatHeader="1"')) {
        rewritten = rewritten.slice(0, start) + tag.replace(/\spageBreak="[A-Z]+"/, ` pageBreak="${value}"`)
          + rewritten.slice(end);
      }
    }
  }
  if (rewritten !== section) {
    entries[SECTION_ENTRY] = strToU8(rewritten);
    changed = true;
  }

  if (!changed) {
    return hwpxBytes;
  }
  return packHwpx(entries);
}

// OCF packaging: `mimetype` is the first entry and stored uncompressed.
function packHwpx(entries) {
  const ordered = { mimetype: [entries.mimetype, { level: 0 }] };
  for (const [name, data] of Object.entries(entries)) {
    if (name !== 'mimetype') {
      ordered[name] = data;
    }
  }
  return zipSync(ordered);
}

// The body is ordinary top-level text: rhwp and Hancom paginate it and honour the paragraph
// page-break attribute. rhwp 0.8.6 does not always move a table or figure that starts near a page
// bottom to the next page (it draws it below the body area), and keep-with-next is not always
// kept; it also splits a floating table marked not to split. Reading the rendered layout back,
// paginate marks every body table no taller than a page as not to split (for Hancom) and puts a
// page break before (1) the first table or figure drawn below the body area that a break can still
// move, (2) a heading or table title left at a page end and (3) a split table that fits one page
// (the form table that closes the body included), each together with the headings and titles it keeps with, and
// repeats until nothing changes. What remains is reported.
const PAGINATION_PASSES = 6;
// A table is kept on one page when its rendered height (a repeated header row counted once) is at
// most this share of the body height; the rest leaves room for the table title.
export const SHORT_TABLE_SHARE = 0.95;

function paginate(rawBytes, form) {
  const breaks = new Set();
  const tableBreaks = new Map();
  let out = normalizeExport(rawBytes, breaks, tableBreaks);
  let passes = 0;
  for (; passes < PAGINATION_PASSES; passes += 1) {
    const flow = bodyFlow(out, form);
    const natural = (k) => k > 0 && flow.pages[k] > flow.lastPages[k - 1];
    const chainStart = (k) => {
      let start = k;
      while (start > 0 && flow.keep[start - 1] && flow.lastPages[start - 1] === flow.pages[k]) {
        start -= 1;
      }
      return start;
    };
    const movable = (k) => k > 0 && !natural(k) && !breaks.has(flow.offset + k);
    const candidates = [];
    const firstOverflow = flow.overflow.findIndex((over, k) => over && movable(chainStart(k)));
    if (firstOverflow >= 0) {
      candidates.push(chainStart(firstOverflow));
    }
    const fits = (k) => flow.tableHeights[k] > 0 && flow.tableHeights[k] <= flow.bodyHeight * SHORT_TABLE_SHARE;
    let tablesChanged = false;
    for (let k = 0; k < flow.summary; k += 1) {
      const value = fits(k) ? 'NONE' : 'CELL';
      if (flow.tableHeights[k] > 0 && tableBreaks.get(flow.offset + k) !== value) {
        tableBreaks.set(flow.offset + k, value);
        tablesChanged = true;
      }
      if (fits(k) && flow.pages[k] < flow.lastPages[k]) {
        candidates.push(chainStart(k));
      }
    }
    for (let i = 0; i + 1 < flow.pages.length; i += 1) {
      if (flow.keep[i] && flow.pages[i + 1] > flow.lastPages[i]) {
        candidates.push(chainStart(i));
      }
    }
    if (flow.endTable && flow.pages[flow.summary] < flow.lastPages[flow.summary]) {
      candidates.push(chainStart(flow.summary));
    }
    const added = candidates.filter(movable).map((k) => breaks.add(flow.offset + k));
    if (added.length === 0 && !tablesChanged) {
      break;
    }
    out = normalizeExport(rawBytes, breaks, tableBreaks);
  }
  const flow = bodyFlow(out, form);
  const keepViolations = [];
  for (let i = 0; i + 1 < flow.pages.length; i += 1) {
    if (flow.keep[i] && flow.pages[i + 1] > flow.lastPages[i]) {
      keepViolations.push(i);
    }
  }
  return {
    bytes: out,
    layout: {
      pageBreaks: breaks.size,
      keepViolations,
      overflow: flow.overflow.flatMap((over, i) => (over ? [i] : [])),
      lineOverflow: flow.lineOverflow.flatMap((over, i) => (over ? [i] : [])),
      unresolved: flow.unresolved,
      summarySplit: flow.endTable && flow.pages[flow.summary] < flow.lastPages[flow.summary],
      splitTables: flow.pages.flatMap((page, k) => (k < flow.summary && page < flow.lastPages[k]
        && flow.tableHeights[k] > 0 && flow.tableHeights[k] <= flow.bodyHeight * SHORT_TABLE_SHARE ? [k] : [])),
    },
  };
}

// First and last rendered page of every top-level paragraph of the body (from the form's body
// start through the paragraph that ends it: the form's closing table or the last paragraph), with
// its keep-with-next flag and own text. Index i of every array is top-level paragraph
// `offset + i`; `summary` is the index of the closing paragraph and `endTable` says whether it
// holds a form table.
export async function inspectBodyFlow(hwpxBytes, form) {
  await ensureWasm();
  return bodyFlow(hwpxBytes, form);
}

function bodyFlow(hwpxBytes, form) {
  const entries = unzipSync(hwpxBytes);
  const xml = strFromU8(entries[SECTION_ENTRY]);
  const header = strFromU8(entries['Contents/header.xml']);
  const location = bodyLocation(xml, form ?? detectForm(xml));
  const all = topLevelParagraphRanges(xml);
  const offset = location.startIdx;
  const ranges = all.slice(offset, location.endIdx + 1);
  const keepIds = new Set([...header.matchAll(/<hh:paraPr id="(\d+)"[^>]*>[\s\S]*?<\/hh:paraPr>/g)]
    .filter((m) => /keepWithNext="1"/.test(m[0])).map((m) => m[1]));
  const keep = ranges.map((r) => keepIds.has(/paraPrIDRef="(\d+)"/.exec(xml.slice(r.start, r.end))[1]));
  const texts = ranges.map((r) => {
    const own = xml.slice(r.start, r.end).replace(/<hp:tbl\b[\s\S]*<\/hp:tbl>/g, '');
    return [...own.matchAll(/<hp:t>([^<]*)<\/hp:t>/g)].map((m) => m[1]).join('').slice(0, 40);
  });

  const doc = new HwpDocument(new Uint8Array(hwpxBytes));
  const pages = Array(ranges.length).fill(undefined);
  const lastPages = Array(ranges.length).fill(undefined);
  const overflow = Array(ranges.length).fill(false);
  // a body text line drawn a little below the body area is rhwp's own line placement; Hancom
  // places lines itself, so these are reported but no page break is added for them
  const lineOverflow = Array(ranges.length).fill(false);
  const tableHeights = Array(ranges.length).fill(0);
  const tableParts = Array(ranges.length).fill(0);
  // a table drawn over several pages repeats its header row on each; that copy is not counted
  const repeatedHeaderPx = ranges.map((r) => {
    const table = /<hp:tbl\b[^>]*repeatHeader="1"[^>]*>[\s\S]*?<\/hp:tr>/.exec(xml.slice(r.start, r.end));
    const heights = table ? [...table[0].matchAll(/<hp:cellSz\b[^>]*\bheight="(\d+)"/g)].map((m) => Number(m[1])) : [];
    return heights.length ? (Math.max(...heights) * 96) / 7200 : 0;
  });
  let bodyHeight = Infinity;
  const mark = (paraIdx, page, bottom, limit, textLine = false) => {
    const k = paraIdx - offset;
    if (k >= 0 && k < pages.length) {
      if (pages[k] === undefined || page < pages[k]) {
        pages[k] = page;
      }
      if (lastPages[k] === undefined || page > lastPages[k]) {
        lastPages[k] = page;
      }
      if (bottom > limit + 1) {
        (textLine ? lineOverflow : overflow)[k] = true;
      }
    }
  };
  for (let page = 0; page < doc.pageCount(); page += 1) {
    const info = JSON.parse(doc.getPageInfo(page));
    const limit = info.height - info.marginBottom;
    bodyHeight = Math.min(bodyHeight, limit - info.marginTop);
    for (const run of JSON.parse(doc.getPageTextLayout(page)).runs ?? []) {
      // text in a table cell reports the top-level paragraph that carries the table
      mark(run.parentParaIdx ?? run.paraIdx, page, run.y + run.h, limit, run.parentParaIdx === undefined);
    }
    for (const control of JSON.parse(doc.getPageControlLayout(page)).controls ?? []) {
      if ((control.stableIndex?.length ?? 0) === 3) {
        mark(control.paraIdx, page, control.y + control.h, limit);
        const k = control.paraIdx - offset;
        if (control.type === 'table' && k >= 0 && k < ranges.length) {
          tableHeights[k] += control.h - (tableParts[k] > 0 ? repeatedHeaderPx[k] : 0);
          tableParts[k] += 1;
        }
      }
    }
  }
  // paragraphs without a rendered run or table (empty paragraphs) take the previous page; they
  // are listed so a check can tell an empty line from a paragraph the layout did not report
  const unresolved = [];
  for (let k = 0; k < pages.length; k += 1) {
    if (pages[k] === undefined) {
      if (texts[k]) {
        unresolved.push(k);
      }
      pages[k] = k === 0 ? 0 : lastPages[k - 1];
      lastPages[k] = pages[k];
    }
  }
  doc.free?.();
  return { offset, pages, lastPages, keep, texts, overflow, lineOverflow, unresolved, tableHeights, bodyHeight,
    summary: ranges.length - 1, endTable: location.endTable !== null };
}

async function ensureWasm() {
  if (!wasmReady) {
    const wasm = readFileSync(new URL('../node_modules/@rhwp/core/rhwp_bg.wasm', import.meta.url));
    wasmReady = initWasm({ module_or_path: wasm });
  }
  await wasmReady;
}

// A new empty top-level paragraph right before the paragraph that ends the body; returns its index.
function openBodyParagraph(doc) {
  const anchor = resolveAnchor(doc);
  parseOk(doc.splitParagraph(SECTION, anchor.endIdx, 0));
  return anchor.endIdx;
}

function insertStyledParagraph(doc, text, style) {
  const paraIdx = openBodyParagraph(doc);
  parseOk(doc.insertText(SECTION, paraIdx, 0, text));
  parseOk(doc.applyStyle(SECTION, paraIdx, style.style));
  parseOk(doc.setParaShapeId(SECTION, paraIdx, style.paraPr));
  if (style.format) {
    parseOk(doc.applyParaFormat(SECTION, paraIdx, JSON.stringify(style.format)));
  }
  if (text.length > 0) {
    parseOk(doc.setCharShapeId(SECTION, paraIdx, 0, text.length, style.charPr));
  }
}

function previousParagraphHoldsTable(doc) {
  const anchor = resolveAnchor(doc);
  const previous = anchor.endIdx > anchor.startIdx ? topLevelParagraphRanges(anchor.xml)[anchor.endIdx - 1] : null;
  return Boolean(previous) && /<hp:tbl\b/.test(anchor.xml.slice(previous.start, previous.end));
}

function insertFigureGrid(doc, block, projectRoot, afterTable = false) {
  const images = block.images ?? [];
  if (images.length === 0) {
    throw new Error('figure_grid requires at least one image');
  }
  const columns = block.columns ?? 2;
  const rows = Math.ceil(images.length / columns);
  // Institute-form (<caption>) figures carry the caption in an extra last row and the
  // table is not split across pages, so a figure never loses its caption to the next page.
  const captionRow = block.captionStyle === 'angle';
  const anchor = resolveAnchor(doc);
  const tableWidth = generatedTableWidthHu(anchor);
  const cellWidth = Math.floor(tableWidth / columns);
  // treated as a character: Hancom moves it whole to the next page when it does not fit (a
  // floating table marked not to split is drawn past the page bottom and clipped there)
  const table = createBodyTable(doc, rows + (captionRow ? 1 : 0), columns, Array(columns).fill(cellWidth),
    { inline: true });
  parseOk(doc.setTableProperties(
    SECTION,
    table.paraIdx,
    table.controlIdx,
    JSON.stringify({ borderFillId: FIGURE_TABLE_BORDER_FILL_ID }),
  ));
  const pictureSpecs = [];
  const rowHeights = Array(rows).fill(1);

  for (const [index, imagePath] of images.entries()) {
    const image = readImage(readFileSync(resolve(projectRoot, imagePath)), imagePath);
    const cell = tempCellMetricsHu(doc, table, index);
    const width = cell.innerWidth;
    const height = Math.max(1, Math.round(width * image.height / image.width));
    const rowHeight = height + cell.paddingTop + cell.paddingBottom;
    rowHeights[Math.floor(index / columns)] = Math.max(rowHeights[Math.floor(index / columns)], rowHeight);
    pictureSpecs.push({ index, imagePath, image, width, height });
  }
  for (let row = 0; row < rows; row += 1) {
    setTempFigureRowProperties(doc, table, row, columns, rowHeights[row]);
  }
  // Figure and <caption> stay on one page. A figure that cannot fit one page with its caption is
  // rejected: split over pages its caption row could end up alone on the next page.
  if (captionRow) {
    const needed = rowHeights.reduce((sum, h) => sum + h, 0) + captionRowHu(captionText(block), tableWidth);
    if (needed > usablePageFlowHu(anchor.xml)) {
      throw new Error(`figure_grid "${block.caption}" is taller than one page with its caption; `
        + 'use fewer images per figure, more columns, or a wider-than-tall image');
    }
    parseOk(doc.setTableProperties(SECTION, table.paraIdx, table.controlIdx,
      JSON.stringify({ pageBreak: FIGURE_TABLE_NO_SPLIT })));
  }

  for (const spec of pictureSpecs) {
    const picture = insertDecodedPicture(doc, table, spec.imagePath, spec.width, spec.height, spec.image);
    parseOk(doc.setPictureProperties(
      SECTION,
      picture.paraIdx,
      picture.controlIdx,
      JSON.stringify({
        width: spec.width,
        height: spec.height,
        treatAsChar: true,
        vertRelTo: 'PARA',
        horzRelTo: 'PARA',
      }),
    ));
    parseOk(doc.copyControl(SECTION, picture.paraIdx, TOP_LEVEL_PATH, picture.controlIdx));
    const path = tableCellPath(table.controlIdx, spec.index, 0);
    parseOk(doc.pasteInternalInCellByPath(
      SECTION,
      table.paraIdx,
      path,
      doc.getCellParagraphLengthByPath(SECTION, table.paraIdx, path),
    ));
    parseOk(doc.deletePictureControl(SECTION, picture.paraIdx, picture.controlIdx));
  }

  if (captionRow) {
    const captionCell = rows * columns;
    fillTempCell(doc, table, captionCell, captionText(block), CAPTION_STYLE, false);
    // the caption row carries its estimated height so the renderer counts it when it decides
    // whether the figure still fits on the page
    const captionHeight = captionRowHu(captionText(block), tableWidth);
    for (let col = 0; col < columns; col += 1) {
      parseOk(doc.setCellProperties(SECTION, table.paraIdx, table.controlIdx, captionCell + col,
        JSON.stringify({ borderFillId: FIGURE_CELL_BORDER_FILL_ID, height: captionHeight })));
    }
    if (columns > 1) {
      parseOk(doc.mergeTableCells(SECTION, table.paraIdx, table.controlIdx, rows, 0, rows, columns - 1));
    }
  }
  const carrier = captionRow ? { spacingBefore: 200 } : FIGURE_CARRIER_FORMAT;
  parseOk(doc.applyParaFormat(SECTION, table.paraIdx, JSON.stringify(afterTable
    ? { ...carrier, spacingBefore: AFTER_TABLE_SPACING }
    : carrier)));
}

function insertDecodedPicture(doc, table, imagePath, width, height, image) {
  try {
    return parseOk(doc.insertPictureEx(
      JSON.stringify({
        sectionIdx: SECTION,
        paraIdx: table.paraIdx,
        // Pictures use logical offsets, including the inline table controls.
        // A text-only length can insert before the table and invalidate its index.
        charOffset: doc.getLogicalLength(SECTION, table.paraIdx),
        cellPath: TOP_LEVEL_PATH,
        width,
        height,
        naturalWidthPx: Math.round(image.width),
        naturalHeightPx: Math.round(image.height),
        extension: image.extension,
        description: imagePath,
      }),
      new Uint8Array(image.data),
    ));
  } catch (error) {
    throw new ImageDecodeError(imagePath, error);
  }
}

function insertContentTable(doc, block, spaceBefore = false) {
  const headers = block.headers ?? [];
  if (headers.length === 0) {
    throw new Error('table requires at least one header');
  }
  const rows = block.rows ?? [];
  const colCount = headers.length;
  const tableWidth = generatedTableWidthHu(resolveAnchor(doc));
  const ratios = block.colWidthRatios ?? Array(colCount).fill(1);
  const ratioSum = ratios.reduce((sum, ratio) => sum + ratio, 0);
  const colWidths = ratios.map((ratio) => Math.max(1, Math.floor(tableWidth * ratio / ratioSum)));
  const table = createBodyTable(doc, rows.length + 1, colCount, colWidths, { inline: false });
  parseOk(doc.setTableProperties(SECTION, table.paraIdx, table.controlIdx, JSON.stringify({ repeatHeader: true })));
  const leftColumns = headers.map((_, col) => rows.some(
    (values) => [...String(values[col] ?? '')].length >= TABLE_TEXT_COLUMN_MIN_CHARS));

  for (const [col, header] of headers.entries()) {
    fillTempCell(doc, table, col, String(header), TABLE_TEXT_STYLE);
    parseOk(doc.setCellProperties(
      SECTION,
      table.paraIdx,
      table.controlIdx,
      col,
      JSON.stringify({ borderFillId: TABLE_HEADER_BORDER_FILL_ID, isHeader: true }),
    ));
  }
  for (const [row, values] of rows.entries()) {
    for (let col = 0; col < colCount; col += 1) {
      fillTempCell(doc, table, (row + 1) * colCount + col, String(values[col] ?? ''),
        leftColumns[col] ? { ...TABLE_TEXT_STYLE, format: TABLE_BODY_LEFT_FORMAT } : TABLE_TEXT_STYLE);
    }
  }
  for (let cellIdx = 0; cellIdx < (rows.length + 1) * colCount; cellIdx += 1) {
    parseOk(doc.setCellProperties(SECTION, table.paraIdx, table.controlIdx, cellIdx,
      JSON.stringify(TABLE_CELL_PADDING)));
  }

  // Merges go last so linear cell indices above still address the full grid;
  // validate guarantees covered cells are empty, so nothing is discarded.
  for (const merge of block.merges ?? []) {
    parseOk(doc.mergeTableCells(
      SECTION,
      table.paraIdx,
      table.controlIdx,
      merge.row,
      merge.col,
      merge.row + merge.rowSpan - 1,
      merge.col + merge.colSpan - 1,
    ));
  }

  if (spaceBefore) {
    parseOk(doc.applyParaFormat(SECTION, table.paraIdx, JSON.stringify({ spacingBefore: AFTER_TABLE_SPACING })));
  }
}

// Content tables are created floating so a long one can split by rows. Once the body is laid out,
// a table no taller than SHORT_TABLE_SHARE of the body height is treated as a character, like a
// figure: Hancom then moves it whole to the next page when it does not fit. A floating table marked
// not to split is instead drawn past the page bottom and clipped in Hancom (user check,
// 2026-09-29), and rhwp 0.8.6 splits it anyway. Longer tables stay floating and split by rows
// (pageBreak CELL) with the header row repeated.
const TABLE_SPLIT_BY_CELL = 2; // rhwp: 0 NONE, 1 TABLE, 2 CELL
function placeContentTables(doc) {
  const flow = bodyFlow(doc.exportHwpx(), documentForms.get(doc));
  const { xml } = resolveAnchor(doc);
  const ranges = topLevelParagraphRanges(xml);
  for (let k = 0; k < flow.summary; k += 1) {
    const paraIdx = flow.offset + k;
    const text = xml.slice(ranges[paraIdx].start, ranges[paraIdx].end);
    const tag = /<hp:tbl\b[^>]*>/.exec(text);
    if (!tag || !tag[0].includes('repeatHeader="1"')) {
      continue;
    }
    const short = flow.tableHeights[k] > 0 && flow.tableHeights[k] <= flow.bodyHeight * SHORT_TABLE_SHARE;
    if (short) {
      // rhwp draws a table treated as a character with its stored row heights; store the heights
      // of the text plus the cell margins first
      fitTableRows(doc, paraIdx, (current) => current.indexOf('<hp:tbl', topLevelParagraphRanges(current)[paraIdx].start),
        { header: true });
    }
    parseOk(doc.setTableProperties(SECTION, paraIdx, 0, JSON.stringify(short
      ? { treatAsChar: true, pageBreak: 0 }
      : { pageBreak: TABLE_SPLIT_BY_CELL })));
  }
}

// The table is created directly in a new body paragraph before the paragraph that ends the body. Content tables
// start floating (placeContentTables treats the short ones as characters afterwards); figures are
// treated as characters from the start and never split.
function createBodyTable(doc, rowCount, colCount, colWidths, { inline = true } = {}) {
  const paraIdx = openBodyParagraph(doc);
  const before = doc.getParagraphCount(SECTION);
  // created inline first: rhwp applies colWidths only to treat-as-char tables
  const table = parseOk(doc.createTableEx(JSON.stringify({
    sectionIdx: SECTION,
    paraIdx,
    charOffset: 0,
    rowCount,
    colCount,
    treatAsChar: true,
    colWidths,
  })));
  if (!inline) {
    parseOk(doc.setTableProperties(SECTION, table.paraIdx, table.controlIdx, JSON.stringify({ treatAsChar: false, vertRelTo: 'Para', horzRelTo: 'Para', vertOffset: 0, horzOffset: 0 })));
  }
  // rhwp adds an empty paragraph after the new table; it would print as a blank line
  if (doc.getParagraphCount(SECTION) > before && doc.getParagraphLength(SECTION, table.paraIdx + 1) === 0) {
    parseOk(doc.deleteParagraph(SECTION, table.paraIdx + 1));
  }
  return table;
}

function fillTempCell(doc, table, cellIdx, text, style, tableChar = true) {
  const path = tableCellPath(table.controlIdx, cellIdx, 0);
  parseOk(doc.insertTextInCellByPath(SECTION, table.paraIdx, path, 0, text));
  styleCellParagraph(doc, table.paraIdx, table.controlIdx, cellIdx, 0, text.length, style);
  if (tableChar && text.length > 0) {
    parseOk(doc.applyCharFormatInCell(SECTION, table.paraIdx, table.controlIdx, cellIdx, 0, 0, text.length,
      JSON.stringify(TABLE_CHAR_FORMAT)));
  }
}

function tempCellMetricsHu(doc, table, cellIdx) {
  const props = parseOk(doc.getCellProperties(SECTION, table.paraIdx, table.controlIdx, cellIdx));
  const paddingLeft = Number(props.paddingLeft);
  const paddingRight = Number(props.paddingRight);
  return {
    innerWidth: Math.max(1, Number(props.width) - paddingLeft - paddingRight),
    paddingTop: Number(props.paddingTop),
    paddingBottom: Number(props.paddingBottom),
  };
}

function setTempFigureRowProperties(doc, table, row, columns, height) {
  for (let col = 0; col < columns; col += 1) {
    parseOk(doc.setCellProperties(
      SECTION,
      table.paraIdx,
      table.controlIdx,
      row * columns + col,
      JSON.stringify({ borderFillId: FIGURE_CELL_BORDER_FILL_ID, height }),
    ));
  }
}

function styleCellParagraph(doc, parentParaIdx, controlIdx, cellIdx, cellParaIndex, textLength, style) {
  parseOk(doc.applyCellStyle(SECTION, parentParaIdx, controlIdx, cellIdx, cellParaIndex, style.style));
  parseOk(doc.setCellParaShapeId(SECTION, parentParaIdx, controlIdx, cellIdx, cellParaIndex, style.paraPr));
  if (style.format) {
    parseOk(doc.applyParaFormatInCell(SECTION, parentParaIdx, controlIdx, cellIdx, cellParaIndex,
      JSON.stringify(style.format)));
  }
  if (textLength > 0) {
    parseOk(doc.setCharShapeIdInCell(SECTION, parentParaIdx, controlIdx, cellIdx, cellParaIndex, 0, textLength, style.charPr));
  }
}

function resolveAnchor(doc) {
  const xml = sectionXml(doc);
  const form = documentForms.get(doc);
  return { xml, form, ...bodyLocation(xml, form) };
}

function sectionXml(doc) {
  return strFromU8(unzipSync(doc.exportHwpx())[SECTION_ENTRY]);
}

function usablePageFlowHu(xml) {
  const page = /<hp:pagePr[^>]*height="(\d+)"/.exec(xml);
  const margin = /<hp:margin[^>]*top="(\d+)"[^>]*bottom="(\d+)"/.exec(xml);
  const header = /<hp:margin[^>]*header="(\d+)"[^>]*footer="(\d+)"/.exec(xml);
  if (!page || !margin) {
    throw new Error('section is missing pagePr/margin');
  }
  return Number(page[1]) - Number(margin[1]) - Number(margin[2])
    - (header ? Number(header[1]) + Number(header[2]) : 0);
}

// Generated tables and figures span the body width (page width minus the side margins).
function generatedTableWidthHu(anchor) {
  const page = /<hp:pagePr[^>]*width="(\d+)"/.exec(anchor.xml);
  const margin = /<hp:margin[^>]*left="(\d+)"[^>]*right="(\d+)"/.exec(anchor.xml);
  if (!page || !margin) {
    throw new Error('section is missing pagePr/margin');
  }
  return Math.max(1, Number(page[1]) - Number(margin[1]) - Number(margin[2]) - TABLE_WIDTH_SAFETY_INSET_HU);
}

function tagEnd(xml, tagName, start) {
  const tokenRe = new RegExp(`<${tagName}(?=[\\s/>])[^>]*>|</${tagName}>`, 'g');
  tokenRe.lastIndex = start;
  let depth = 0;
  let match;
  while ((match = tokenRe.exec(xml)) !== null) {
    const token = match[0];
    if (token.startsWith('</')) {
      depth -= 1;
      if (depth === 0) {
        return tokenRe.lastIndex;
      }
    } else if (isSelfClosingTag(token)) {
      if (depth === 0) {
        return tokenRe.lastIndex;
      }
    } else {
      depth += 1;
    }
  }
  throw new Error(`unclosed ${tagName} tag at ${start}`);
}

function parseAttrs(header) {
  const attrs = {};
  for (const match of header.matchAll(/([\w:-]+)="([^"]*)"/g)) {
    attrs[match[1]] = match[2];
  }
  return attrs;
}

// PNG (raster) or SVG (vector); an SVG is embedded as drawn (lib/svg.js).
function readImage(buffer, imagePath) {
  if (!looksLikeSvg(buffer)) {
    return readPngImage(buffer, imagePath);
  }
  try {
    return { ...svgInfo(buffer), data: buffer, extension: 'svg' };
  } catch (error) {
    throw new ImageDecodeError(imagePath, error);
  }
}

function readPngImage(buffer, imagePath) {
  try {
    if (buffer.length < 24
      || buffer[0] !== 0x89
      || buffer[1] !== 0x50
      || buffer[2] !== 0x4e
      || buffer[3] !== 0x47) {
      throw new Error('only PNG and SVG images are supported');
    }
    const chunks = pngChunks(buffer);
    const ihdr = chunks.find((chunk) => chunk.type === 'IHDR')?.data;
    if (!ihdr) {
      throw new Error('PNG missing IHDR');
    }
    const width = ihdr.readUInt32BE(0);
    const height = ihdr.readUInt32BE(4);
    const idat = Buffer.concat(chunks.filter((chunk) => chunk.type === 'IDAT').map((chunk) => chunk.data));
    inflateSync(idat);
    return { width, height, data: buffer, extension: 'png' };
  } catch (error) {
    throw new ImageDecodeError(imagePath, error);
  }
}

function pngChunks(buffer) {
  const chunks = [];
  let offset = 8;
  while (offset < buffer.length) {
    const length = buffer.readUInt32BE(offset);
    const type = buffer.subarray(offset + 4, offset + 8).toString('ascii');
    const data = buffer.subarray(offset + 8, offset + 8 + length);
    chunks.push({ type, data });
    offset += 12 + length;
    if (type === 'IEND') {
      break;
    }
  }
  return chunks;
}

function tableCellPath(controlIndex, cellIndex, cellParaIndex) {
  return JSON.stringify([{ controlIndex, cellIndex, cellParaIndex }]);
}

function parseOk(result) {
  const parsed = typeof result === 'string' ? JSON.parse(result) : result;
  if (parsed?.ok === false) {
    throw new Error(`rhwp operation failed: ${JSON.stringify(parsed)}`);
  }
  return parsed;
}

function isSelfClosingTag(token) {
  return token.endsWith('/>');
}
